<?php
// Warranty cases own their approvals, custody receipts, donor units and append-only trail.
function wc_ready(){if(!array_key_exists('WC_READY',$GLOBALS))$GLOBALS['WC_READY']=!array_diff(['warranty_cases','warranty_case_events','warranty_donor_units','warranty_donor_components'],db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN));return $GLOBALS['WC_READY'];}
function wc_require($action=null){if(!wc_ready())throw new Exception('Ask Admin to enable Warranty Cases first.');if($action&&!can_action($action))throw new Exception('Your role cannot perform this warranty action.');}
function wc_install(){if(current_user()['role']!=='Admin')throw new Exception('Admin setup required.');
 db()->exec("CREATE TABLE IF NOT EXISTS warranty_cases(id BIGINT AUTO_INCREMENT PRIMARY KEY,case_ref VARCHAR(100) NOT NULL UNIQUE,request_key CHAR(64) NOT NULL UNIQUE,platform VARCHAR(40) NOT NULL,order_no VARCHAR(100) NOT NULL,order_record_id BIGINT NULL,original_product_id INT NOT NULL,claim_type VARCHAR(20) NOT NULL,component_name VARCHAR(180) NULL,customer_name VARCHAR(120) NOT NULL,contact VARCHAR(100) NOT NULL,issue TEXT NOT NULL,evidence_path VARCHAR(500) NULL,requested_qty INT NOT NULL,approved_qty INT NULL,status VARCHAR(40) NOT NULL DEFAULT 'For Review',created_by INT NOT NULL,approved_by INT NULL,decision_notes TEXT NULL,source_mode VARCHAR(40) NULL,source_product_id INT NULL,source_platform VARCHAR(40) NULL,source_ns_id BIGINT NULL,source_unit INT NULL,component_code VARCHAR(80) NULL,component_capacity INT NULL,received_date DATE NULL,received_qty INT NOT NULL DEFAULT 0,receipt_ref VARCHAR(120) NULL,receipt_key CHAR(64) NULL UNIQUE,receipt_ns_id BIGINT NULL,linked_return_id BIGINT NULL,received_by INT NULL,released_by INT NULL,released_date DATE NULL,replacement_ref VARCHAR(120) NULL,outflow_id BIGINT NULL,donor_id BIGINT NULL,closed_by INT NULL,revision INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(order_record_id),INDEX(original_product_id),INDEX(receipt_ns_id),INDEX(linked_return_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 db()->exec("CREATE TABLE IF NOT EXISTS warranty_case_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,case_id BIGINT NOT NULL,event_type VARCHAR(80) NOT NULL,user_id INT NOT NULL,user_name VARCHAR(120) NOT NULL,user_role VARCHAR(40) NOT NULL,details_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(case_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 db()->exec("CREATE TABLE IF NOT EXISTS warranty_donor_units(id BIGINT AUTO_INCREMENT PRIMARY KEY,non_sellable_id BIGINT NOT NULL,unit_no INT NOT NULL,product_id INT NOT NULL,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(non_sellable_id,unit_no),INDEX(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 db()->exec("CREATE TABLE IF NOT EXISTS warranty_donor_components(id BIGINT AUTO_INCREMENT PRIMARY KEY,donor_id BIGINT NOT NULL,component_code VARCHAR(80) NOT NULL,component_name VARCHAR(180) NOT NULL,capacity INT NOT NULL,used_qty INT NOT NULL DEFAULT 0,UNIQUE(donor_id,component_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");unset($GLOBALS['WC_READY']);audit('Enable Warranty Cases','System','Warranty','Add four case, trail and donor tables; no inventory posting.');}
function wc_case($id,$lock=false){wc_require();$r=studio_query('SELECT * FROM warranty_cases WHERE id=?'.($lock?' FOR UPDATE':''),[(int)$id])->fetch();if(!$r)throw new Exception('Warranty case not found.');return $r;}
function wc_event($id,$title,$details){$u=current_user();studio_query('INSERT INTO warranty_case_events(case_id,event_type,user_id,user_name,user_role,details_json) VALUES(?,?,?,?,?,?)',[$id,$title,$u['id'],$u['name'],$u['role'],json_encode($details,JSON_THROW_ON_ERROR)]);$r=wc_case($id);if($r['order_record_id'])om_event($r['order_record_id'],null,'Warranty: '.$title,['warranty_reference'=>$r['case_ref'],'reason'=>$details['remarks']??$title,'stock_changed'=>!empty($details['stock_changed'])]);audit($title,'Warranty Case',$r['case_ref'],json_encode($details,JSON_THROW_ON_ERROR));}
function wc_text($v,$label,$max=2000,$min=3){$v=trim((string)$v);if(mb_strlen($v)<$min||mb_strlen($v)>$max)throw new Exception('Enter '.$label.' ('.$min.'–'.$max.' characters).');return $v;}
function wc_product($sku){$p=studio_query('SELECT * FROM products WHERE master_sku=? AND active=1',[trim((string)$sku)])->fetch();if(!$p)throw new Exception('Select an active exact Master SKU.');return $p;}
function wc_revision($r,$input){if((int)$r['revision']!==(int)($input['revision']??0))throw new Exception('Case changed. Refresh and review the latest record.');}
function wc_create($i,$file=null){wc_require('wc_create');$key=$i['request_key']??'';if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new Exception('Reopen the warranty form.');$pl=$i['platform']??'';if(!in_array($pl,array_merge(array_keys(om_shops()),['Other Purchase']),true))throw new Exception('Select purchase source.');$no=wc_text($i['order_no']??'','purchase / order reference',100,1);$p=wc_product($i['original_sku']??'');$type=$i['claim_type']??'';if(!in_array($type,['Whole Part','Component Only'],true))throw new Exception('Select Whole Part or Component Only.');$component=$type==='Component Only'?wc_text($i['component_name']??'','component name',180):null;$name=wc_text($i['customer_name']??'','customer name',120);$contact=wc_text($i['contact']??'','contact',100);$issue=wc_text($i['issue']??'','issue');$qty=whole_number($i['qty']??'','Claim quantity',1);if($qty>9999)throw new Exception('Quantity is too large.');$o=$pl==='Other Purchase'?null:or_find_reference($pl,om_shops()[$pl],$no);if($o){$no=$o['order_no'];if(!isset(om_existing_totals($o['id'])[$p['id']])){$found=false;foreach(studio_query('SELECT components_json FROM om_lines WHERE order_id=?',[$o['id']]) as $line)foreach(json_decode($line['components_json'],true)?:[] as $c)if((int)$c['product_id']===(int)$p['id'])$found=true;if(!$found)throw new Exception('Selected original product is not in the matched order. Check the original item.');}}elseif(empty($i['unrecorded_ack']))throw new Exception('Order not found. Confirm purchase evidence will be reviewed for an unrecorded order.');
 return process_transaction(function()use($i,$key,$pl,$no,$p,$type,$component,$name,$contact,$issue,$qty,$o,$file){$old=studio_query('SELECT id,created_by FROM warranty_cases WHERE request_key=? FOR UPDATE',[$key])->fetch();if($old){if((int)$old['created_by']!==current_user()['id'])throw new Exception('Form key belongs to another user.');return (int)$old['id'];}$path=null;if($file&&!empty($file['tmp_name'])){validate_upload_file($file,['pdf','jpg','jpeg','png']);$path=store_upload($file,'warranty_cases','WRT');}studio_query('INSERT INTO warranty_cases(case_ref,request_key,platform,order_no,order_record_id,original_product_id,claim_type,component_name,customer_name,contact,issue,evidence_path,requested_qty,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[next_ref('WRT').'-'.bin2hex(random_bytes(3)),$key,$pl,$no,$o['id']??null,$p['id'],$type,$component,$name,$contact,$issue,$path,$qty,current_user()['id']]);$id=(int)db()->lastInsertId();wc_event($id,'Claim recorded',['claim_type'=>$type,'original_sku'=>$p['master_sku'],'component'=>$component,'requested_qty'=>$qty,'order_match'=>$o?'Original order linked':'Original order not in system','remarks'=>$issue,'stock_changed'=>false]);return $id;});}
function wc_donor($ns,$unit,$code,$capacity,$qty,$pid,$date,$name){$n=studio_query('SELECT * FROM non_sellable WHERE id=? FOR UPDATE',[$ns])->fetch();if(!$n||$n['reversed_by_request']!==null||studio_source($n)||(int)$n['product_id']!==$pid||$n['txn_date']>$date||(!in_array(packaging_kind($n['condition_type']),['damaged'],true)&&$n['condition_type']!=='Incomplete / For Parts'))throw new Exception('Choose a matching damaged / Incomplete For Parts source.');$left=(int)$n['qty']-release_total($ns);if($unit<1||$unit>$left)throw new Exception('Identify an available physical unit number within this Non-Sellable record.');if(repack_active_source($ns))throw new Exception('This source is already assigned to a repackaging batch.');$d=studio_query('SELECT * FROM warranty_donor_units WHERE non_sellable_id=? AND unit_no=? FOR UPDATE',[$ns,$unit])->fetch();if($d)foreach(studio_query('SELECT * FROM warranty_donor_components WHERE donor_id=?',[$d['id']]) as $existing)if(norm($existing['component_name'])===norm($name)&&$existing['component_code']!==$code)throw new Exception('Reuse the existing component code for this donor: '.$existing['component_code'].'.');$part=$d?studio_query('SELECT * FROM warranty_donor_components WHERE donor_id=? AND component_code=? FOR UPDATE',[$d['id'],$code])->fetch():false;if($part&&(int)$part['capacity']!==$capacity)throw new Exception('Use the existing component capacity for this physical unit: '.$part['capacity'].'.');$used=(int)($part['used_qty']??0);if($qty>$capacity-$used)throw new Exception('This physical unit does not have enough of that component remaining. Use another inspected donor.');return ['ns'=>$n,'unit'=>$unit,'remaining_units'=>$left,'donor'=>$d?:null,'component'=>$part?:null,'used'=>$used,'capacity'=>$capacity];}
function wc_decide($id,$i){wc_require('wc_decide');return process_transaction(function()use($id,$i){$r=wc_case($id,true);wc_revision($r,$i);if(!in_array($r['status'],['For Review','Approved','Received'],true))throw new Exception('Only an unreleased case can be reviewed.');$notes=wc_text($i['remarks']??'','review remarks');$decision=$i['decision']??'';if(!in_array($decision,['Approve','Reject'],true)||empty($i['review_ack']))throw new Exception('Review and acknowledge the claim first.');if($decision==='Reject'){if($r['received_qty'])throw new Exception('Item already received. Record a reviewed disposition before rejecting; do not discard its custody trail.');studio_query("UPDATE warranty_cases SET status='Rejected',decision_notes=?,approved_by=?,revision=revision+1 WHERE id=?",[$notes,current_user()['id'],$id]);wc_event($id,'Claim rejected',['remarks'=>$notes,'stock_changed'=>false]);return;}$qty=whole_number($i['approved_qty']??'','Approved quantity',1);if($qty>(int)$r['requested_qty']||($r['received_qty']&&$qty!==(int)$r['approved_qty']))throw new Exception('Approved quantity must fit the claim and cannot change after receiving.');$mode=$i['source_mode']??'';if(!in_array($mode,$r['claim_type']==='Whole Part'?['Sellable Whole']:['Damaged Component','Open Sellable'],true))throw new Exception('Select the correct replacement source for this claim.');$p=wc_product($i['source_sku']??'');$pl=null;$ns=null;$unit=null;$code=null;$cap=null;if($mode!=='Damaged Component')$pl=stock_platform($i['source_platform']??'');if($r['claim_type']==='Component Only'){$code=mb_strtoupper(trim((string)($i['component_code']??'')));if(!preg_match('/^[A-Z0-9][A-Z0-9_-]{1,79}$/D',$code))throw new Exception('Use a stable component code, e.g. RADIATOR-CAP. Reuse the same code for the same component.');$cap=whole_number($i['component_capacity']??'','Components per donor unit',1);if($cap>1000||$qty>$cap)throw new Exception('This case uses one physical donor unit; approved quantity cannot exceed its inspected component capacity.');if($mode==='Damaged Component'){$ns=whole_number($i['source_ns_id']??'','Source NS record',1);$unit=whole_number($i['source_unit']??'','Physical unit number',1);wc_donor($ns,$unit,$code,$cap,$qty,(int)$p['id'],date('Y-m-d'),$r['component_name']);}}$status=$r['received_qty']?'Received':'Approved';studio_query('UPDATE warranty_cases SET approved_qty=?,source_mode=?,source_product_id=?,source_platform=?,source_ns_id=?,source_unit=?,component_code=?,component_capacity=?,approved_by=?,decision_notes=?,status=?,revision=revision+1 WHERE id=?',[$qty,$mode,$p['id'],$pl,$ns,$unit,$code,$cap,current_user()['id'],$notes,$status,$id]);wc_event($id,'Replacement approved',['approved_qty'=>$qty,'mode'=>$mode,'source_sku'=>$p['master_sku'],'ns_source'=>$ns,'unit'=>$unit,'component_code'=>$code,'components_per_unit'=>$cap,'remarks'=>$notes,'stock_changed'=>false]);});}
function wc_receipt_guard($platform,$refs){if(!wc_ready())return;$refs=array_values(array_filter(array_map(fn($s)=>mb_strtoupper(trim((string)$s)),$refs)));if(!$refs)return;$q=studio_query('SELECT case_ref FROM warranty_cases WHERE platform=? AND received_qty>0 AND linked_return_id IS NULL AND receipt_ref IN ('.implode(',',array_fill(0,count($refs),'?')).') LIMIT 1',array_merge([$platform],$refs));if($ref=$q->fetchColumn())throw new Exception('This parcel is already received on warranty '.$ref.'. Link the existing receipt instead of posting it again.');}
function wc_link_used($returnId){if(!wc_ready())return 0;return (int)studio_query('SELECT COALESCE(SUM(received_qty),0) FROM warranty_cases WHERE linked_return_id=?',[$returnId])->fetchColumn();}
function wc_receive_plan($id,$i){wc_require('wc_receive');$r=wc_case($id);if($r['status']!=='Approved'||$r['received_qty'])throw new Exception('Choose an approved case not yet received.');$date=process_date($i['txn_date']??'');if($date>date('Y-m-d'))throw new Exception('Receiving date cannot be in the future.');require_open_inventory_date($date);$ref=mb_strtoupper(wc_text($i['receipt_ref']??'','returned parcel / tracking reference',120));$linked=(int)($i['linked_return_id']??0);$n=null;$pr=null;
 if($linked){if($r['claim_type']!=='Whole Part')throw new Exception('Component custody cannot be linked as a whole-item inventory receipt.');$pr=warranty_return($linked,true);if((int)$pr['product_id']!==(int)$r['original_product_id']||$pr['platform']!==$r['platform']||or_canonical($r['platform'],$pr['original_ref'])!==$r['order_no']||$date<$pr['txn_date'])throw new Exception('Return line does not match the original order, product or date.');if((int)$r['approved_qty']>(int)$pr['damaged_qty']-warranty_used($linked))throw new Exception('That existing return quantity is already assigned to another warranty.');$n=studio_query('SELECT * FROM non_sellable WHERE id=?',[$pr['non_sellable_id']])->fetch();if(!$n||$n['reversed_by_request']!==null)throw new Exception('Original defective receipt is unavailable.');}
 else{wc_receipt_guard($r['platform'],[$ref]);ix_parcel_guard($r['platform'],[$ref]);foreach(studio_query("SELECT id,batch_ref,rows_json FROM return_batches WHERE status IN ('Review','Posted')") as $b)foreach(json_decode($b['rows_json'],true)?:[] as $line)if(($line['platform']??'')===$r['platform']&&in_array($ref,array_map(fn($x)=>mb_strtoupper(trim((string)$x)),[$line['receipt_reference']??'',$line['tracking_no']??'']),true))throw new Exception('Parcel exists in return batch '.$b['batch_ref'].'. Link its posted return line or resolve the open review first.');}
 $key=hash('sha256',$r['platform'].'|'.$ref.'|'.$r['original_product_id'].'|'.($r['claim_type']==='Whole Part'?'WHOLE':norm($r['component_name'])));if(studio_query('SELECT id FROM warranty_cases WHERE receipt_key=?',[$key])->fetchColumn())throw new Exception('This warranty parcel/item is already recorded.');$p=['case'=>$r,'date'=>$date,'reference'=>$ref,'key'=>$key,'linked'=>$linked,'linked_ns'=>$n,'linked_return'=>$pr,'qty'=>(int)$r['approved_qty'],'stock_effect'=>$r['claim_type']==='Whole Part'&&!$linked?'Non-Sellable +'.$r['approved_qty'].'; sellable unchanged':'Existing receipt / component custody only; no whole-item stock addition'];$p['digest']=hash('sha256',json_encode($p));return $p;}
function wc_receive($id,$input,$digest,$ack){wc_require('wc_receive');if(!$ack)throw new Exception('Acknowledge actual physical receiving.');return process_transaction(function()use($id,$input,$digest){wc_case($id,true);$p=wc_receive_plan($id,$input);if(!hash_equals($p['digest'],(string)$digest))throw new Exception('Receipt / case changed. Review receiving again.');$r=$p['case'];$ns=$p['linked_ns']['id']??null;if($r['claim_type']==='Whole Part'&&!$p['linked']){studio_query("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,'Damaged / Leak','Warranty Receiving','Warranty Hold','Warranty Case',0,?,?)",[$p['date'],$r['platform']==='Other Purchase'?null:$r['platform'],$r['case_ref'],$r['original_product_id'],$p['qty'],'Defective warranty receipt; parcel '.$p['reference'],current_user()['id']]);$ns=(int)db()->lastInsertId();}studio_query("UPDATE warranty_cases SET status='Received',received_date=?,received_qty=?,receipt_ref=?,receipt_key=?,receipt_ns_id=?,linked_return_id=?,received_by=?,revision=revision+1 WHERE id=?",[$p['date'],$p['qty'],$p['reference'],$p['key'],$ns,$p['linked']?:null,current_user()['id'],$id]);wc_event($id,'Defective item received',['qty'=>$p['qty'],'parcel'=>$p['reference'],'linked_return_id'=>$p['linked']?:null,'non_sellable_id'=>$ns,'remarks'=>$p['stock_effect'],'stock_changed'=>$r['claim_type']==='Whole Part'&&!$p['linked']]);return $ns;});}
function wc_release_plan($id){wc_require('wc_release');$r=wc_case($id);if($r['status']!=='Received'||(int)$r['received_qty']!==(int)$r['approved_qty'])throw new Exception('ICO must first receive / link the approved defective item.');$date=date('Y-m-d');require_open_inventory_date($date);$p=active_product($r['source_product_id']);studio_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$p['id']]);unset($GLOBALS['OM_RESERVED']);$s=stock_row($p['id']);$donor=null;$units=$r['source_mode']==='Open Sellable'?1:(int)$r['approved_qty'];if($r['source_mode']==='Damaged Component'){$donor=wc_donor((int)$r['source_ns_id'],(int)$r['source_unit'],$r['component_code'],(int)$r['component_capacity'],(int)$r['approved_qty'],(int)$p['id'],$date,$r['component_name']);$effect='No whole-item quantity change. Record removed components on this exact damaged unit.';}
 else{check_platform_alignment($p['id']);om_assert_available($p['id'],$units);om_assert_available($p['id'],$units,$r['source_platform']);$effect=$r['source_mode']==='Open Sellable'?'Sellable −1 whole item; Non-Sellable Incomplete / For Parts +1. No second whole-item deduction for the component.':'Sellable and physical −'.$units.' whole item(s).';}
 $plan=['case'=>$r,'date'=>$date,'product'=>['id'=>(int)$p['id'],'sku'=>$p['master_sku'],'name'=>$p['name']],'units'=>$units,'stock'=>['sellable'=>(int)$s['current'],'non_sellable'=>(int)$s['nonsellable'],'physical'=>(int)$s['physical'],'allocation'=>$r['source_platform']?platform_qty($r['source_platform'],$p['id']):null,'reserved'=>om_reserved($p['id'])],'donor'=>$donor,'effect'=>$effect];$plan['digest']=hash('sha256',json_encode($plan));return $plan;}
function wc_release($id,$digest,$reference,$inspection,$ack){wc_require('wc_release');if(!$ack)throw new Exception('Confirm inspection and actual replacement handover.');$ref=wc_text($reference,'replacement tracking / handover reference',120);$inspection=wc_text($inspection,'inspection / compatibility remarks');return process_transaction(function()use($id,$digest,$ref,$inspection){wc_case($id,true);$p=wc_release_plan($id);if(!hash_equals($p['digest'],(string)$digest))throw new Exception('Stock, donor components or approval changed. Review the release again.');$r=$p['case'];$pid=$p['product']['id'];$ns=null;$donor=null;$out=null;$before=$p['stock'];if($r['source_mode']==='Sellable Whole'){studio_query("INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,dedupe_key,remarks,user_id) VALUES(?,?,?,?,?,?,'Warranty Replacement',?,?,?)",[$p['date'],$r['source_platform'],$r['case_ref'],$pid,$r['case_ref'],(int)$r['approved_qty'],hash('sha256','warranty-case|'.$id),'Warranty case replacement; '.$ref.'; '.$inspection,current_user()['id']]);$out=(int)db()->lastInsertId();change_platform_stock($r['source_platform'],$pid,-(int)$r['approved_qty'],$r['case_ref'],$p['date']);check_platform_alignment($pid);}
 else{if($r['source_mode']==='Open Sellable'){studio_query("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,1,'Incomplete / For Parts','Open for Warranty Component','Incomplete / For Parts','Warranty Donor',1,?,?)",[$p['date'],$r['source_platform'],$r['case_ref'],$pid,'Opened one whole item; '.$r['component_name'].' removed; '.$inspection,current_user()['id']]);$ns=(int)db()->lastInsertId();change_platform_stock($r['source_platform'],$pid,-1,$r['case_ref'],$p['date']);check_platform_alignment($pid);$unit=1;}else{$ns=(int)$r['source_ns_id'];$unit=(int)$r['source_unit'];}
 studio_query('INSERT IGNORE INTO warranty_donor_units(non_sellable_id,unit_no,product_id,created_by) VALUES(?,?,?,?)',[$ns,$unit,$pid,current_user()['id']]);$donor=(int)studio_query('SELECT id FROM warranty_donor_units WHERE non_sellable_id=? AND unit_no=? FOR UPDATE',[$ns,$unit])->fetchColumn();studio_query('INSERT IGNORE INTO warranty_donor_components(donor_id,component_code,component_name,capacity) VALUES(?,?,?,?)',[$donor,$r['component_code'],$r['component_name'],$r['component_capacity']]);$part=studio_query('SELECT * FROM warranty_donor_components WHERE donor_id=? AND component_code=? FOR UPDATE',[$donor,$r['component_code']])->fetch();if((int)$part['capacity']!==(int)$r['component_capacity']||(int)$r['approved_qty']>(int)$part['capacity']-(int)$part['used_qty'])throw new Exception('The inspected component has already been removed or its capacity changed.');studio_query('UPDATE warranty_donor_components SET used_qty=used_qty+? WHERE id=?',[$r['approved_qty'],$part['id']]);studio_query("UPDATE non_sellable SET status='Incomplete / For Parts',remarks=CONCAT(COALESCE(remarks,''),?) WHERE id=?",[' | '.$r['case_ref'].' unit '.$unit.': '.$r['component_code'].' removed '.$r['approved_qty'].'; '.$inspection,$ns]);if((int)stock_row($pid)['physical']!==$before['physical'])throw new Exception('Whole-item count changed during component handling.');}
 studio_query("UPDATE warranty_cases SET status='Replacement Released',released_date=?,released_by=?,replacement_ref=?,outflow_id=?,donor_id=?,revision=revision+1 WHERE id=?",[$p['date'],current_user()['id'],$ref,$out,$donor,$id]);$after=stock_row($pid);wc_event($id,'Replacement released',['mode'=>$r['source_mode'],'source_sku'=>$p['product']['sku'],'qty'=>(int)$r['approved_qty'],'component_code'=>$r['component_code'],'donor_unit_id'=>$donor,'non_sellable_id'=>$ns,'outflow_id'=>$out,'before'=>$before,'after'=>['sellable'=>$after['current'],'non_sellable'=>$after['nonsellable'],'physical'=>$after['physical']],'handover_reference'=>$ref,'remarks'=>$inspection.'; '.$p['effect'],'stock_changed'=>$r['source_mode']!=='Damaged Component']);return $p;});}
function wc_close($id,$i){wc_require('wc_close');$notes=wc_text($i['remarks']??'','customer follow-up');if(empty($i['customer_ack']))throw new Exception('Confirm the customer was informed.');return process_transaction(function()use($id,$i,$notes){$r=wc_case($id,true);wc_revision($r,$i);if($r['status']!=='Replacement Released')throw new Exception('Only a released case can be closed.');studio_query("UPDATE warranty_cases SET status='Closed',closed_by=?,revision=revision+1 WHERE id=?",[current_user()['id'],$id]);wc_event($id,'Case closed',['remarks'=>$notes,'stock_changed'=>false]);});}
function wc_protected_ns($id){if(!wc_ready())return false;return (bool)studio_query('SELECT id FROM warranty_donor_units WHERE non_sellable_id=? LIMIT 1',[$id])->fetchColumn()||(bool)studio_query('SELECT id FROM warranty_cases WHERE receipt_ns_id=? AND received_qty>0 LIMIT 1',[$id])->fetchColumn();}
function wc_ns_guard($id){if(wc_protected_ns($id))throw new Exception('This Non-Sellable record has warranty custody / removed components. Review Warranty Cases; generic release, repacking or reversal cannot restore it as a complete item.');}
function wc_guard_count($id){if(!wc_ready())return;$b=count_batch($id);$meta=json_decode($b['filter_json']??'{}',true)?:[];if(($meta['count_scope']??'All Conditions')==='Sellable')return;foreach(count_lines($id) as $l)if(studio_query('SELECT id FROM warranty_donor_units WHERE product_id=? LIMIT 1',[$l['product_id']])->fetchColumn()||studio_query('SELECT id FROM warranty_cases WHERE original_product_id=? AND receipt_ns_id IS NOT NULL LIMIT 1',[$l['product_id']])->fetchColumn())throw new Exception('This product has protected warranty / incomplete units. Use Sellable Only for a sellable count; do not count an incomplete unit as complete stock.');}
function wc_reversal_guard($plan){if(!wc_ready())return;foreach($plan['non_sellable']??[] as $n)wc_ns_guard($n['id']);foreach($plan['outflows']??[] as $o)if(studio_query('SELECT id FROM warranty_cases WHERE outflow_id=? LIMIT 1',[$o['id']])->fetchColumn())throw new Exception('This outflow belongs to a released warranty case. Do not reverse its ledger separately from its case history.');foreach($plan['returns']??[] as $r)if(wc_link_used($r['id']))throw new Exception('This receipt is assigned to a warranty case; preserve its linked custody history.');}
